-- CHAMBA 028 — Precios admin (si faltaba 027) + publicar chambas sin límite de cliente para adminSET statement_timeout = '120s';-- ── precios_catalogo (idempotente) ──────────────────────────────────────────CREATE TABLE IF NOT EXISTS precios_catalogo (  service_slug    TEXT PRIMARY KEY,  suggested_price NUMERIC(10, 2) NOT NULL CHECK (suggested_price >= 0),  min_price_ratio NUMERIC(4, 3) NOT NULL DEFAULT 0.5    CHECK (min_price_ratio > 0 AND min_price_ratio <= 1),  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),  updated_by      UUID REFERENCES profiles(id));CREATE INDEX IF NOT EXISTS idx_precios_catalogo_updated  ON precios_catalogo (updated_at DESC);ALTER TABLE precios_catalogo ENABLE ROW LEVEL SECURITY;DROP POLICY IF EXISTS "precios: public read" ON precios_catalogo;CREATE POLICY "precios: public read"  ON precios_catalogo FOR SELECT  USING (true);DROP POLICY IF EXISTS "precios: admin write" ON precios_catalogo;CREATE POLICY "precios: admin write"  ON precios_catalogo FOR ALL  USING (    EXISTS (      SELECT 1 FROM profiles p      WHERE p.id = auth.uid() AND p.role::text = 'admin'    )  )  WITH CHECK (    EXISTS (      SELECT 1 FROM profiles p      WHERE p.id = auth.uid() AND p.role::text = 'admin'    )  );CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS get_precios_catalogo CASCADE;CREATE OR REPLACE FUNCTION get_precios_catalogo()RETURNS JSONBLANGUAGE sqlSTABLESECURITY DEFINERSET search_path = publicAS $$  SELECT COALESCE(    jsonb_agg(      jsonb_build_object(        'service_slug', service_slug,        'suggested_price', suggested_price,        'min_price_ratio', min_price_ratio,        'updated_at', updated_at      )      ORDER BY service_slug    ),    '[]'::jsonb  )  FROM precios_catalogo;$$;GRANT EXECUTE ON FUNCTION get_precios_catalogo() TO anon, authenticated;CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS admin_upsert_precios_batch CASCADE;CREATE OR REPLACE FUNCTION admin_upsert_precios_batch(  p_admin_id UUID,  p_rows     JSONB)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_row   JSONB;  v_slug  TEXT;  v_price NUMERIC;  v_ratio NUMERIC;  v_count INT := 0;BEGIN  IF NOT EXISTS (    SELECT 1 FROM profiles    WHERE id = p_admin_id AND role::text = 'admin'  ) THEN    RETURN jsonb_build_object('success', false, 'error', 'Solo administradores');  END IF;  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN    RETURN jsonb_build_object('success', false, 'error', 'p_rows debe ser un array JSON');  END IF;  IF jsonb_array_length(p_rows) = 0 THEN    RETURN jsonb_build_object('success', false, 'error', 'p_rows no puede estar vacío');  END IF;  FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows)  LOOP    v_slug := lower(trim(v_row->>'service_slug'));    v_price := NULLIF(trim(v_row->>'suggested_price'), '')::NUMERIC;    v_ratio := COALESCE(      NULLIF(trim(v_row->>'min_price_ratio'), '')::NUMERIC,      0.5    );    IF v_slug IS NULL OR v_slug = '' THEN      RETURN jsonb_build_object('success', false, 'error', 'service_slug requerido en cada fila');    END IF;    IF v_price IS NULL OR v_price < 0 THEN      RETURN jsonb_build_object(        'success', false,        'error', format('Precio inválido para slug: %s', v_slug)      );    END IF;    IF v_ratio <= 0 OR v_ratio > 1 THEN      RETURN jsonb_build_object(        'success', false,        'error', format('min_price_ratio inválido para slug: %s', v_slug)      );    END IF;    INSERT INTO precios_catalogo (      service_slug, suggested_price, min_price_ratio, updated_by, updated_at    ) VALUES (      v_slug, v_price, v_ratio, p_admin_id, now()    )    ON CONFLICT (service_slug) DO UPDATE SET      suggested_price = EXCLUDED.suggested_price,      min_price_ratio = EXCLUDED.min_price_ratio,      updated_by      = EXCLUDED.updated_by,      updated_at      = now();    v_count := v_count + 1;  END LOOP;  RETURN jsonb_build_object('success', true, 'updated', v_count);EXCEPTION  WHEN OTHERS THEN    RETURN jsonb_build_object('success', false, 'error', SQLERRM);END;$$;GRANT EXECUTE ON FUNCTION admin_upsert_precios_batch(UUID, JSONB) TO anon, authenticated;-- ── create_client_job: admin no cuenta límite de 2 solicitudes activas ────────CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS create_client_job CASCADE;CREATE OR REPLACE FUNCTION create_client_job(  p_created_by       UUID,  p_title            TEXT,  p_description      TEXT,  p_category         TEXT,  p_pay_amount       NUMERIC,  p_address          TEXT,  p_lat              DOUBLE PRECISION,  p_lng              DOUBLE PRECISION,  p_duration_hours   NUMERIC DEFAULT 2,  p_required_workers INTEGER DEFAULT 1,  p_scheduled_at     TIMESTAMPTZ DEFAULT NULL,  p_media_urls       TEXT[] DEFAULT '{}')RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_job    jobs%ROWTYPE;  v_fee    NUMERIC;  v_payout NUMERIC;  v_active INT;  v_max    INT := 2;  v_role   TEXT;BEGIN  SELECT role::text INTO v_role FROM profiles WHERE id = p_created_by;  IF v_role IS NULL THEN    RETURN jsonb_build_object('success', false, 'error', 'Perfil no encontrado');  END IF;  IF v_role <> 'admin' THEN    v_active := count_client_active_jobs(p_created_by);    IF v_active >= v_max THEN      RETURN jsonb_build_object(        'success', false,        'error', 'Ya tenés 2 solicitudes activas. Cuando una figure como finalizada, podés publicar otra.',        'code', 'client_active_limit',        'active_count', v_active,        'max_allowed', v_max      );    END IF;  END IF;  v_fee    := ROUND(p_pay_amount * 0.05, 2);  v_payout := ROUND(p_pay_amount * 0.95, 2);  INSERT INTO jobs (    title, description, category, status,    pay_amount, platform_fee, worker_payout,    address, lat, lng, scheduled_at,    duration_hours, required_workers, slots_taken,    media_urls, created_by  ) VALUES (    p_title, p_description, p_category, 'open',    p_pay_amount, v_fee, v_payout,    p_address, p_lat, p_lng, p_scheduled_at,    p_duration_hours, p_required_workers, 0,    COALESCE(p_media_urls, '{}'), p_created_by  )  RETURNING * INTO v_job;  RETURN jsonb_build_object('success', true, 'job', to_jsonb(v_job));EXCEPTION  WHEN OTHERS THEN    RETURN jsonb_build_object('success', false, 'error', SQLERRM);END;$$;GRANT EXECUTE ON FUNCTION create_client_job TO anon, authenticated;